CustomCss:
  /* Season page: episodes as a 3-up card grid instead of a list */
  #childrenContent .itemsContainer.vertical-list { display: flex !important; flex-direction: row !important; flex-wrap: wrap !important; gap: 1.6em 1.2em; align-items:
  flex-start; }
  #childrenContent .itemsContainer.vertical-list > .listItem { flex: 0 0 calc(33.333% - 0.8em) !important; width: auto !important; max-width: calc(33.333% - 0.8em); margin: 0
  !important; padding: 0 !important; }
  #childrenContent .listItem-content { display: flex; flex-direction: column; align-items: stretch; }
  #childrenContent .listItemImage.listItemImage-large { width: 100% !important; height: auto !important; aspect-ratio: 16 / 9; margin: 0 !important; }
  #childrenContent .listItemBody { padding: 0.6em 0 0 0; }
  #childrenContent .listItemBody > .listItemBodyText:first-child { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; line-height:
  1.3em; height: 2.6em; }
  #childrenContent .listItem-overview { display: -webkit-box; -webkit-line-clamp: 1; -webkit-box-orient: vertical; overflow: hidden; }
  #childrenContent .listItem-overview p { margin: 0; }
  #childrenContent .listViewUserDataButtons { align-self: flex-start; padding-top: 0.2em; }

/* hide the next-up section in shows */
.nextUpSection { display: none; }
